INSERT INTO public.exam_questions (subject_id,subject_name,year,position,text,options,answer,explanation) VALUES
(5,'Biology','2017',1,'Which one of the following Ethiopian biological research institutes is known for housing a major gene bank in Africa?','["Addis Ababa University Biology Department", "Institute of Biodiversity Conservation", "Aklilu Lemma Institute of Pathobiology", "Armauer Hansen Research Institute"]'::jsonb,1,''),
(5,'Biology','2017',2,'A grade 12 student marked two dots close to each other using a pen on a piece of paper and observed them under a microscope. The two dots appeared well separated under the microscope. This was due to','["resolution", "magnification", "staining", "mounting"]'::jsonb,0,''),
(5,'Biology','2017',3,'From the following alternatives select the common features that are found both in animal and plant cells.','["Cell membrane, nucleus, cytoplasm, lysosome and Golgi apparatus", "Cell membrane, nucleus, cytoplasm, mitochondria and endoplasmic reticulum", "Cell membrane, nucleus, cytoplasm, chloroplast and Golgi apparatus", "Cell membrane, nucleus, cytoplasm, large vacuole and Golgi apparatus"]'::jsonb,1,''),
(5,'Biology','2017',4,'A biology teacher grouped his students into two groups and ordered group I to place a slice of potato in hypertonic solution and group II in hypotonic solution. What will happen to the potato slice in group I and group II?','["turgid while for group II it will be flaccid.", "haemolyzed while for group II it will be flaccid.", "flaccid while for group II it will be turgid.", "turgid while for group II there will be no change."]'::jsonb,2,''),
(5,'Biology','2017',5,'A man eats only vegetables, beans, banana and orange for one week continuously in his lunch and dinner. For this man, what nutrients are most likely missed in his meal to be a balanced diet?','["Carbohydrates", "Lipids", "Proteins", "Minerals"]'::jsonb,1,''),
(5,'Biology','2017',6,'Which of the following is correct about the process of digestion or absorption of food in the small intestine?','["Proteins are converted into amino acids by the action of hydrochloric acid and amylase.", "Bile emulsifies fats to increase the surface area to make it easier for lipase.", "Water is reabsorbed into the small intestine and metabolic wastes are excreted.", "Glucose and non-hydrolyzed starch molecules are absorbed through the lacteal."]'::jsonb,1,''),
(5,'Biology','2017',7,'In an experiment, students wanted to prove that enzymatic digestion begins in the mouth using certain chewed food coated with their own saliva. In order to get a positive result for their experiment, what type of food sample and testing solution should the students use?','["Potato and iodine solution", "Meat and Benedict''s solution", "Fish and sodium hydroxide solution", "Bread and copper sulphate solution"]'::jsonb,0,''),
(5,'Biology','2017',8,'Compared to the inhaled air, what are the percentage of nitrogen, oxygen and carbon dioxide gases in exhaled air, respectively?','["80%, 16% and 4%", "80%, 4% and 16%", "16%, 4% and 80%", "4%, 16% and 80%"]'::jsonb,0,''),
(5,'Biology','2017',9,'Three students carried out different experiments in exhaled air as indicated below. Student I – uses cold glass and blue cobalt chloride paper Student II – uses ice cubes Student III – uses tube containing lime solution and straw Based on their setup, which student plans to demonstrate the presence of water vapour and carbon dioxide, respectively?','["II and III", "I and II", "II and I", "I and III"]'::jsonb,3,''),
(5,'Biology','2017',10,'If your body cannot make enough red blood cells, which one of the following mineral-rich foods can correct this problem?','["Iron-rich food", "Calcium-rich food", "Iodine-rich food", "Sodium-rich food"]'::jsonb,0,''),
(5,'Biology','2017',11,'A biology teacher provided common names of three organisms: human being, dog and housefly, to his students to write the correct scientific names of each organism. In which of the following ways should the students write the correct scientific names, respectively?','["Homo Sapiens, Canis Familiaris and Musca Domestica", "Homo sapiens, Canis familiaris and Musca domestica", "homo sapiens, Canis familiaris and Musca domestica", "Homo sapiens, Canis familiaris and musca domestica"]'::jsonb,1,''),
(5,'Biology','2017',12,'Identify the typical examples for division Gymnospermae and Angiospermae, respectively?','["Mosses and ferns", "Liverworts and palm trees", "Grasses and legumes", "Juniper and roses"]'::jsonb,3,''),
(5,'Biology','2017',13,'A student made a collection of plants having flowers and seeds from his locality and compared their embryo, leaves and stems using a hand lens. He found that all his collections contain a single seed leaf embryo, long and thin leaves with parallel veins, and stems with scattered vascular bundles. Which option contains plants that can be categorized under his collection?','["Grasses, orchids, teff and roses", "Grasses, orchids, teff and beans", "Grasses, sunflowers, teff and maize", "Grasses, orchids, teff and maize"]'::jsonb,3,''),
(5,'Biology','2017',14,'This item is based on the following diagram of a simple food chain: Leaves → Grasshoppers → Rodents → Leopards What will happen if the number of rodents significantly decreases?','["an increase in the number of leopards.", "fewer grasshoppers in the chain.", "no change in the number of leopard.", "an increase in the number of grasshoppers."]'::jsonb,3,''),
(5,'Biology','2017',15,'Which of the following is NOT a key process involved in the carbon cycle?','["Evaporation", "Cellular respiration", "Photosynthesis", "Decomposition"]'::jsonb,0,''),
(5,'Biology','2017',16,'Which of the following is correct about mitosis? It is a division of','["somatic cells to make daughter cells with half chromosome.", "sex cells to make identical daughter cells with doubled chromosome.", "somatic cells to make identical daughter cells.", "sex cells to make different daughter cells."]'::jsonb,2,''),
(5,'Biology','2017',17,'Which one of the following features is common for mitosis and meiosis? They both involve','["replication of DNA and the formation of daughter cells.", "production of daughter cells identical to the parent cell.", "formation of cells with the same chromosome number as parent cell.", "spermatogenesis and oogenesis processes in males and females."]'::jsonb,0,''),
(5,'Biology','2017',18,'Which tissues of plant leaves are involved in waterproofing, major photosynthetic, and major gas exchange activities, respectively?','["Guard cells, palisade mesophyll and epidermis", "Guard cells, palisade mesophyll and spongy mesophyll", "Waxy cuticle, palisade mesophyll and spongy mesophyll", "Waxy cuticle, palisade mesophyll and epidermis"]'::jsonb,2,''),
(5,'Biology','2017',19,'Which of the following is correct about the movement of water in plants? It moves','["against a water potential gradient.", "across the phloem tissue by diffusion.", "across the tissues of a plant by osmosis.", "by using energy until it reaches to the xylem."]'::jsonb,2,''),
(5,'Biology','2017',20,'What will happen to the growth of the plant when you remove indole-acetic acid (IAA) from the main shoot part of the plant?','["The plant will bush out.", "It stimulates dropping of leaves.", "The main shoot of the plant elongates.", "The growth of side shoots will slow down."]'::jsonb,0,''),
(5,'Biology','2017',21,'Which of the following is correct about animals? They are','["Respire, excrete, autotrophic and reproduce", "Unicellular, excrete, heterotrophic and motility", "Heterotrophic, excrete, motility and grow", "Respire, multicellular, autotrophic and reproduce"]'::jsonb,2,''),
(5,'Biology','2017',22,'A grade 11 student observed and identified some animal groups having closed circulatory system, centralized nervous system with brain and sensory organs. Based on their identification, select one of the following animals that can belong to this group?','["Snails", "Earthworm", "Squid", "Snake"]'::jsonb,2,''),
(5,'Biology','2017',23,'What does it mean if an animal is poikilothermic? It','["changes its body temperature with environmental condition.", "increases its metabolic rate during cold and hot conditions.", "keeps its body temperature constant regardless of external changes.", "produces heat when temperature falls by activating the hypothalamus."]'::jsonb,0,''),
(5,'Biology','2017',24,'Which one of the following statements is correct about the catalytic activities of enzymes? They','["change the overall nature of the products.", "allow reactions in cells to take place quickly.", "alter themselves at the end of biochemical reactions.", "increase the energy required to start a reaction."]'::jsonb,1,''),
(5,'Biology','2017',25,'Four students draw four different big protein structure posters. The contents of each of their structure are displayed in the following table.','["I and IV", "II and III", "I and III", "II and IV"]'::jsonb,2,''),
(5,'Biology','2017',26,'How does the induced-fit model explain enzyme specificity? They','["change the shape of active site slightly to fit substrates precisely.", "have a rigid active site that can just bind to single substrate.", "have multiple active sites that can fit to different substrates.", "bind to whatever the shape of substrate that fits to allosteric site."]'::jsonb,0,''),
(5,'Biology','2017',27,'What happens to the substrate molecule when competitive inhibitor binds with an enzyme? It','["undergoes conformational change.", "cannot bind with the active site.", "binds to the allosteric site temporarily.", "easily binds with the active site."]'::jsonb,1,''),
(5,'Biology','2017',28,'What will happen to the reaction if you add a certain inhibitor or activator to the substrate having allosteric enzyme set up?','["Inhibitor binds to active site to speed up the reaction.", "Inhibitor binds to regulatory site to increase rate of reaction.", "Activator binds to active site to initiate the reaction.", "Activator binds to regulatory site to activate the reaction."]'::jsonb,3,''),
(5,'Biology','2017',29,'Which one of the following classes of enzyme and type of reactions they catalyze is correctly matched?','["Oxidoreductases - transfer functional groups from donor to acceptor", "Transferases - transfer of electrons from one molecule to another", "Ligases - cleave bonds by other means rather than hydrolysis", "Lyases - catalyze the hydrolysis of various bonds"]'::jsonb,2,''),
(5,'Biology','2017',30,'If a given enzyme works only at temperature range of 20 and 45 °C and the potential of hydrogen ions that ranges from 4 to 9. Which one of the following works best during the optimization of these two factors for the enzyme activity?','["Adjusting the temperature below 20°C makes the enzyme more active, hence the temperature at this value is optimal.", "Adjusting the pH above 9 can increase the probability of collisions between the enzyme and the substrate.", "Adjusting the temperature between 20°C and 45°C results little denaturation and increased number of collisions.", "The optimum pH under which this enzyme is most active is found below 4."]'::jsonb,2,''),
(5,'Biology','2017',31,'All of the following features define a chromosome EXCEPT','["contains hundreds to thousands of genes.", "exists in pairs in diploid organisms.", "made up of DNA and protein.", "functional unit of inheritance."]'::jsonb,3,''),
(5,'Biology','2017',32,'Which structural and functional difference is observed between DNA and RNA?','["Both DNA and RNA have the same nitrogenous bases but differ in pentose sugar.", "RNA produces DNA through the process of transcription.", "RNA stores the genetic material while DNA involves in protein synthesis.", "DNA is very stable molecule while RNA is degraded quickly."]'::jsonb,3,''),
(5,'Biology','2017',33,'All of the following events occur during telophase I of meiosis I cell division EXCEPT','["crossing over takes place.", "each of the spindle fibers disappears.", "set of chromosomes come together.", "nuclear envelope reforms."]'::jsonb,0,''),
(5,'Biology','2017',34,'Suppose there was a cross between pea plants with flower positions axial (AA) and terminal (aa) and produced F1 generation. What will be the most probable number of heterozygous dominant individuals obtained if 1000 offspring were produced by self-crossing of F1 generation?','["200", "750", "500", "250"]'::jsonb,2,''),
(5,'Biology','2017',35,'If you have a pea plant of unknown genotype with a green pod color, you obtained all green pod colors of offspring phenotype after a test cross. What was the unknown genotype of the parent? It was','["homozygous dominant.", "homozygous recessive.", "heterozygous dominant.", "incomplete dominant."]'::jsonb,0,''),
(5,'Biology','2017',36,'This item is based on the following examples of genetic inheritance patterns. 1. Inflated and pinched pod forms will have inflated pod form. 2. Red cow and white bull will have roan calf. 3. AA and BB blood type people will have a child with AB blood type. 4. Red and white roses will have a pink rose offspring. From the above patterns of inheritance, which of the following are exemplary for non-Mendelian inheritance?','["1, 2, 3", "1, 3, 4", "1, 2, 4", "2, 3, 4"]'::jsonb,3,''),
(5,'Biology','2017',37,'Farmers want to maintain their sheep with long tails for the next generation through similar sheep from their locality in their breeding program. What process do these farmers apply to keep the desired traits in their program?','["Inbreeding", "Crossbreeding", "Genetic engineering", "Cloning"]'::jsonb,0,''),
(5,'Biology','2017',38,'If progesterone remains high after ovulation, what will be the most likely outcome?','["FSH will be produced rapidly which leads to a new cycle.", "Oestrogen will be decreased, closing down the lining of the uterus.", "Uterus lining will be maintained and prepared for pregnancy.", "Corpus luteum will be regenerated, inhibiting hormone production."]'::jsonb,2,''),
(5,'Biology','2017',39,'The most reliable contraceptive method that prevents travelling of ovum from the ovaries through the fallopian tubes, but requires surgery is','["contraceptive injection.", "spermicide.", "intrauterine device.", "sterilization."]'::jsonb,3,''),
(5,'Biology','2017',40,'Among the following, which one increases the risk to be infected by sexually transmitted infections?','["Have no history of sexually transmitted infections", "Misuse of drugs that inhibit your judgment", "Protective sexual contact and medical treatment", "Consistent use of condoms during intercourse"]'::jsonb,1,'');